'use strict';
const $=s=>document.querySelector(s),el=(tag,text='',cls='')=>{const e=document.createElement(tag);e.textContent=text;if(cls)e.className=cls;return e;};
let state,project,session,busy=false,tab='chat',catalog=[],preferences={},modelRequest=0,refreshing=false,toastTimer;
const key=()=>`agentic:${project?.id}:${$('#provider').value}:${$('#model').value}`;
async function api(path,body){const r=await fetch(path,{method:body===undefined?'GET':'POST',headers:body===undefined?{}:{'Content-Type':'application/json'},body:body===undefined?undefined:JSON.stringify(body)});const d=await r.json();if(!r.ok||d.error)throw Error(d.error||'Error del servidor');return d;}
function error(e){$('#toast').textContent=e.message||String(e);$('#toast').classList.add('visible');clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('#toast').classList.remove('visible'),9000);}
function on(s,event,fn){$(s).addEventListener(event,e=>Promise.resolve(fn(e)).catch(error));}
function option(value,text){const e=el('option',text);e.value=value;return e;}
function sampling(){const out={};document.querySelectorAll('[data-sampling]').forEach(e=>{if(e.value!=='')out[e.dataset.sampling]=+e.value;});return out;}
function savePreferences(){if(!project||!$('#model').value)return;try{sessionStorage.setItem(key(),JSON.stringify({context:+$('#context').value,max_tokens:+$('#max-tokens').value,temperature:+$('#temperature').value,sampling:sampling()}));}catch{}}
function applyPreferences(){let p=preferences[$('#model').value]||{};try{p=JSON.parse(sessionStorage.getItem(key()))||p;}catch{}for(const [id,k,fallback] of [['context','context',16384],['max-tokens','max_tokens',1024],['temperature','temperature',.4]])$('#'+id).value=p[k]??fallback;document.querySelectorAll('[data-sampling]').forEach(e=>e.value=p.sampling?.[e.dataset.sampling]??'');}
async function refresh(){if(refreshing||busy)return;refreshing=true;try{state=await api('/api/state');project=state.projects.find(p=>p.id===state.mobile_project)||state.projects[0];if(!project)throw Error('Proyecto no disponible. Vuelve a vincular desde el Mac.');$('#project').textContent=project.name;$('#project-select').replaceChildren(...state.projects.map(p=>option(p.id,p.name)));$('#project-select').value=project.id;$('#project-select').disabled=busy;$('#breadcrumb').textContent=project.name;$('#instructions').textContent=project.instructions||'Este proyecto aún no tiene instrucciones.';$('#permissions').textContent=`${project.config.root||'Carpeta interna del proyecto'}\nEscritura: ${project.config.write} · Ejecución: ${project.config.execute}`;
if(!state.sessions.some(s=>s.id===session))session=state.sessions[0]?.id;
$('#sessions').replaceChildren(...state.sessions.map(s=>{const b=el('button',s.title,'session'+(s.id===session?' active':''));b.disabled=busy;b.onclick=async()=>{if(busy)return;session=s.id;$('#sidebar').classList.remove('open');$('#sidebar-toggle').setAttribute('aria-expanded','false');await refresh();};return b;}));
if(!$('#provider').options.length){$('#provider').replaceChildren(...state.providers.map(p=>option(p.id,p.name)));$('#provider').value=state.selected_provider;await models();}await messages();await actions();if(tab!=='chat')await renderTab();}finally{refreshing=false;}}
async function models(){const request=++modelRequest,provider=$('#provider').value;try{const d=await api('/api/models?provider='+encodeURIComponent(provider));if(request!==modelRequest)return;catalog=d.models;preferences=d.preferences||{};const old=$('#model').value;$('#model').replaceChildren(...catalog.map(m=>option(m.id,m.name||m.id)));const chosen=catalog.some(m=>m.id===old)?old:state?.selected_models?.[provider];if(catalog.some(m=>m.id===chosen))$('#model').value=chosen;$('#send').disabled=!catalog.length||busy;$('#temperature').disabled=provider==='openai-oauth';document.querySelectorAll('[data-sampling]').forEach(e=>e.disabled=provider==='openai-oauth'||(['top_k','min_p','repetition_penalty'].includes(e.dataset.sampling)&&!d.sampling_extensions));applyPreferences();if(d.loaded_context)$('#context').value=Math.min(+$('#context').value,d.loaded_context);if(tab==='models')await renderTab();}catch(e){if(request!==modelRequest)return;catalog=[];$('#model').replaceChildren(option('','Motor no disponible'));$('#send').disabled=true;error(e);}}
function message(role,content,meta){const a=el('article','','message '+role);a.append(el('div',role==='user'?'TÚ':'AGENTIC STUDIO','message-label'));const body=el('div',content,'message-body');a.append(body);if(meta?.model)a.append(el('div',`${meta.model} · ${meta.seconds??'—'} s${meta.usage?.completion_tokens?' · '+meta.usage.completion_tokens+' tokens':''}`,'message-meta'));$('#messages').append(a);return body;}
async function messages(){if(!session){$('#messages').replaceChildren(el('div','De la idea al archivo.\nConversa y trabaja con tu agente en el Mac.','empty'));return;}const rows=await api('/api/messages?session='+encodeURIComponent(session)+'&limit=40');$('#messages').replaceChildren();for(const m of rows){let meta;try{meta=JSON.parse(m.meta||'{}');}catch{}message(m.role,m.content,meta);}if(!rows.length)$('#messages').append(el('div','¿En qué vamos a trabajar?','empty'));}
async function actions(){if(!session){$('#actions').textContent='Sin acciones pendientes.';$('#resume').disabled=true;return;}const d=await api('/api/proposals?session='+encodeURIComponent(session));$('#actions').replaceChildren();let pending=false;for(const [kind,items] of [['extension',d.extensions||[]],['file',d.files||[]],['command',d.commands||[]]])for(const x of items.filter(a=>a.status==='pending')){pending=true;const card=el('div','','action');card.append(el('b',kind==='extension'?x.name:kind==='file'?x.path:'Terminal del proyecto'),el('pre',kind==='extension'?x.arguments:kind==='file'?x.content:x.command));for(const [text,approve] of [['Aprobar',true],['Rechazar',false]]){const b=el('button',text);b.onclick=async()=>{if(approve&&!confirm('¿Aprobar la acción completa mostrada en esta tarjeta?'))return;b.disabled=true;try{await api(kind==='file'?'/api/proposal/resolve':kind==='command'?'/api/command/resolve':'/api/extension/resolve',{id:x.id,approve});await actions();}catch(e){b.disabled=false;error(e);}};card.append(b);}$('#actions').append(card);}if(!pending)$('#actions').textContent='Ninguna acción pendiente.';$('#resume').disabled=busy||pending||d.run?.status!=='waiting';$('#memory').textContent=d.memory?.summary||'Todavía no hay memoria compactada.';}
function activity(text){const log=$('#activity'),near=log.scrollHeight-log.scrollTop-log.clientHeight<40;log.textContent=(log.textContent+'\n['+new Date().toLocaleTimeString('es-ES')+'] '+text).slice(-40000);if($('#activity-follow').checked&&near)log.scrollTop=log.scrollHeight;}
async function files(){const rows=await api('/api/files?project='+encodeURIComponent(project.id)),query=$('#file-search').value.toLocaleLowerCase();$('#files').replaceChildren(...rows.filter(f=>f.path.toLocaleLowerCase().includes(query)).map(f=>{const b=el('button',f.path,'file-button');b.onclick=async()=>{try{const d=await api('/api/file?project='+encodeURIComponent(project.id)+'&path='+encodeURIComponent(f.path));$('#viewer-title').textContent=f.path;$('#viewer-content').textContent=d.content;$('#viewer').showModal();}catch(e){error(e);}};return b;}));}
function card(title,text){const c=el('div','','card');c.append(el('h3',title),el('p',text));return c;}
async function renderTab(){if(tab==='models'){$('#model-list').replaceChildren(...catalog.map(m=>{const c=card(m.name||m.id,m.id);const b=el('button',m.id===$('#model').value?'Seleccionado':'Usar en conversación','primary');b.disabled=busy;b.onclick=()=>{$('#model').value=m.id;applyPreferences();switchTab('chat');};c.append(b);return c;}));if(!catalog.length)$('#model-list').append(card('Sin modelos disponibles','Actualiza los modelos o inicia un motor en el Mac.'));}
if(tab==='engine'){const d=await api('/api/resources');$('#engine-info').replaceChildren(el('h3',d.engine.running?'Motor del Mac activo':'Motor propio detenido'),el('p',d.engine.running?`${d.engine.engine} · Contexto ${d.engine.context} · ${d.engine.model}`:'Puedes seguir usando un proveedor externo disponible.'),el('p',`Agentic: ${d.app_rss_mb??'—'} MB · Motor: ${d.engine_rss_mb??'—'} MB`),el('p','Carga, descarga, cambio de motor y parada global se controlan desde el Mac.'));}
if(tab==='connections'){$('#connection-info').replaceChildren(el('h3','Proyecto vinculado: '+project.name),el('p','HTTPS · '+location.host),el('p','MCP y navegador del agente se ejecutan en el Mac y conservan los permisos de este proyecto.'),el('p',$('#permissions').textContent));}
if(tab==='activity'&&session){const rows=await api('/api/tool-events?session='+encodeURIComponent(session));$('#event-list').replaceChildren(...rows.slice(-100).map(x=>{const c=card(x.name||x.tool||'Herramienta',x.status||'');c.append(el('pre',JSON.stringify(x,null,2).slice(0,12000),'code'));return c;}));if(!rows.length)$('#event-list').append(card('Sin acciones','La actividad de herramientas aparecerá aquí.'));}}
async function switchTab(name){tab=name;document.querySelectorAll('[data-tab]').forEach(b=>b.classList.toggle('active',b.dataset.tab===name));document.querySelectorAll('.tab').forEach(s=>s.classList.toggle('active',s.id===name+'-tab'));await renderTab();}
async function send(resume=false){if(busy||(!resume&&!$('#prompt').value.trim()))return;if(!session){session=(await api('/api/sessions',{project_id:project.id})).id;await refresh();}savePreferences();busy=true;$('#send').disabled=true;$('#provider').disabled=true;$('#model').disabled=true;$('#new').disabled=true;$('#project-select').disabled=true;$('#stop').classList.remove('hidden');$('#resume').disabled=true;const started=performance.now();let chars=0,tokens,first,seconds,phase='Preparando contexto…';const stats=()=>{$('#status').textContent=[`${(seconds??((performance.now()-started)/1000)).toFixed(1)} s`,tokens!==undefined?tokens+' tokens':chars+' caracteres',tokens&&((performance.now()-started)>0)?(tokens/(seconds??((performance.now()-started)/1000))).toFixed(1)+' tok/s':'',first!==undefined?'primer texto '+first.toFixed(2)+' s':'',phase].filter(Boolean).join(' · ');};const timer=setInterval(stats,500);stats();
try{const body=resume?{session_id:session,resume:true}:{session_id:session,message:$('#prompt').value,provider:$('#provider').value,model:$('#model').value,agent:$('#agent').checked,retrieval:$('#retrieval').checked,context:+$('#context').value,max_tokens:+$('#max-tokens').value,max_steps:+$('#steps').value,temperature:+$('#temperature').value,sampling:sampling()};if(!resume){$('.empty')?.remove();message('user',body.message);}const r=await fetch('/api/chat',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(body)});if(!r.ok)throw Error((await r.json()).error);if(!resume)$('#prompt').value='';const answer=message('assistant',''),reader=r.body.getReader(),decoder=new TextDecoder();let buffer='';function event(e){if(e.type==='delta'){answer.textContent+=e.text;chars+=e.text.length;if(first===undefined)first=(performance.now()-started)/1000;}if(e.type==='activity'){phase=e.text;activity(e.text);}if(e.type==='reasoning')activity('Razonamiento proporcionado por el modelo: '+e.text);if(e.type==='tool_start')activity(e.name+' '+JSON.stringify(e.arguments));if(e.type==='tool')activity(e.name+' '+JSON.stringify(e.result).slice(0,6000));if(e.type==='metrics')tokens=e.usage?.completion_tokens??tokens;if(e.type==='context')$('#context-meter').textContent=`${e.exact?'':'≈ '}${e.estimated} / ${e.budget} tokens${e.compacted?' · compactado':''}`;if(e.type==='waiting')phase='Esperando tu revisión.';if(e.type==='done'){seconds=e.meta.seconds;tokens=e.meta.usage?.completion_tokens??tokens;phase='Completado';}if(e.type==='error')throw Error(e.error);stats();}while(true){const chunk=await reader.read();if(chunk.done)break;buffer+=decoder.decode(chunk.value,{stream:true});let i;while((i=buffer.indexOf('\n'))>=0){const line=buffer.slice(0,i);buffer=buffer.slice(i+1);if(line.trim())event(JSON.parse(line));}}buffer+=decoder.decode();if(buffer.trim())event(JSON.parse(buffer));}catch(e){phase=e.message;activity('ERROR · '+e.message);error(e);}finally{clearInterval(timer);seconds=seconds??(performance.now()-started)/1000;stats();busy=false;$('#send').disabled=!catalog.length;$('#provider').disabled=false;$('#model').disabled=false;$('#new').disabled=false;$('#stop').classList.add('hidden');await refresh().catch(error);}}
on('#compose','submit',e=>{e.preventDefault();return send();});on('#provider','change',models);on('#model','change',applyPreferences);on('#new','click',async()=>{if(busy)return;session=(await api('/api/sessions',{project_id:project.id})).id;await refresh();});on('#refresh','click',async()=>{if(busy)return;await refresh();await models();});on('#resume','click',()=>send(true));on('#stop','click',()=>api('/api/mobile/cancel',{session_id:session}));on('#file-search','input',files);on('#viewer-close','click',()=>$('#viewer').close());on('#activity-clear','click',()=>{$('#activity').textContent='';});on('#reset-sampling','click',()=>{document.querySelectorAll('[data-sampling]').forEach(e=>e.value='');savePreferences();});
document.querySelectorAll('.generation-controls input,[data-sampling]').forEach(e=>e.addEventListener('change',savePreferences));document.querySelectorAll('[data-tab]').forEach(b=>b.onclick=()=>switchTab(b.dataset.tab).catch(error));for(const [button,panel] of [['#sidebar-toggle','#sidebar'],['#inspector-toggle','#inspector']])on(button,'click',async()=>{const open=$(panel).classList.toggle('open');$(button).setAttribute('aria-expanded',String(open));if(panel==='#inspector'&&open)await files();});
on('#export','click',async()=>{if(!session)return;const d=await api('/api/export?session='+encodeURIComponent(session));$('#viewer-title').textContent='Exportar conversación';$('#viewer-content').textContent=d.messages.map(m=>(m.role==='user'?'TÚ':'AGENTIC STUDIO')+'\n'+m.content).join('\n\n');$('#viewer').showModal();});
refresh().then(files).catch(error);
// One lightweight timer, paused while hidden or generating; no extra model engine or polling catalog.
setInterval(()=>{if(document.visibilityState==='visible'&&!busy)actions().catch(error);},5000);

for(const [button,panel,toggle] of [['#sidebar-close','#sidebar','#sidebar-toggle'],['#inspector-close','#inspector','#inspector-toggle']])on(button,'click',()=>{$(panel).classList.remove('open');$(toggle).setAttribute('aria-expanded','false');});

on('#project-select','change',async()=>{if(busy){$('#project-select').value=project.id;return;}const old=project.id;try{await api('/api/mobile/project',{project:$('#project-select').value});session=undefined;$('#activity').textContent='';$('#context-meter').textContent='Presupuesto de contexto por modelo';$('#status').textContent='Sin generación activa';await refresh();await files();}catch(e){$('#project-select').value=old;throw e;}});
